package com.hbm.client.gascentrifuge;
import com.hbm.machine.gascentrifuge.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.resources.ResourceLocation;import net.minecraft.network.chat.Component;import snownee.jade.api.*;import snownee.jade.api.config.IPluginConfig;
@WailaPlugin public final class GasCentrifugeJadePlugin implements IWailaPlugin {
 @Override public void register(IWailaCommonRegistration e){e.registerBlockDataProvider(Provider.INSTANCE,GasCentrifugeBlockEntity.class);e.registerBlockDataProvider(Provider.INSTANCE,GasCentrifugePort.class);}@Override public void registerClient(IWailaClientRegistration e){e.registerBlockComponent(Provider.INSTANCE,GasCentrifugeBlock.class);}
 private enum Provider implements IServerDataProvider<BlockAccessor>,IBlockComponentProvider{INSTANCE;@Override public ResourceLocation getUid(){return GasCentrifugeContent.id("gascentrifuge_state");}@Override public void appendServerData(CompoundTag tag,BlockAccessor accessor){var tile=accessor.getBlockEntity();if(tile instanceof GasCentrifugePort p)tile=p.core();if(tile instanceof GasCentrifugeBlockEntity m)tag.putBoolean("hbm:gascentrifuge_fast",m.fast());}@Override public void appendTooltip(ITooltip tooltip,BlockAccessor accessor,IPluginConfig config){if(accessor.getServerData().getBoolean("hbm:gascentrifuge_fast"))tooltip.add(Component.translatable("item.hbm.upgrade_gc_speed"));}}
}
